"""``tools.trace_to_state`` on synthetic raw traces generated by the JAX engine.

``_engine_trace`` plays a scripted Roark fight through ``step`` and writes what
``tools/trace_battle.lua`` would record: a ``turn`` record at every turn boundary and
``hit``/``move_end`` records for each move in between (docs/tracing.md, "Raw trace
format"). The converter must recover every engine state, the actions and the realized
hits, crits and damage rolls.
"""

from __future__ import annotations

import copy
import itertools
import json
import re
from pathlib import Path

import jax
import jax.numpy as jnp
import numpy as np
import pytest

